"""
    Finds the start of a comment in the line, if any, and returns the line
    up to the comment, the token that started the comment (#, //, or /*),
    and the line after the comment token
    """
def strip_line_comment(line: str) -> object {
    comment_tokens = ['#', '//', '/*'];
    index = 0;
    while (index < len(line)) {
        for token in comment_tokens {
            if (index > (len(line) - len(token))) {
                continue;
            }
            if (
                (line[index:(index + len(token))] == token)
                and ((line[0:index].replace('\\"', '').count('"') % 2) == 0)
            ) {
                return (line[0:index], token, line[(index + len(token)):]);
            }
        }
        index += 1;
    }
    return (line, None, None);
}

"""
    Parses reference designator into a dictionary containing subsite, node,
    and sensor.

    Args:
        reference_designator (str): OOI Instrument Reference Designator

    Returns:
        Dictionary of the parsed reference designator
    """
def ooi_instrument_reference_designator(reference_designator: Any) -> object {
    keys = ["subsite", "node", "sensor"];
    val = reference_designator.split("-");
    values = val[:-2] + ["-".join(val[-2:])];
    return `dict(zip(keys, values));
}
